    { lab:"Snapshot regime — not a live market call", val:regime, sub:"median 7d TVL Δ " + (med30 >= 0 ? "+" : "−") + Math.abs(med30).toFixed(1) + "% · " + fmtPct(posShare, 0) + " of rows growing · n=207 · snapshot 2026-11-14 (no 30d series in snapshot)" }
