function renderCatPanel(){
  var sums = {}, ns = {};
  ROWS.forEach(function(r){ sums[r.cat] = (sums[r.cat]||0) + r.implied; ns[r.cat] = (ns[r.cat]||0) + 1; });
  var order = CATNAMES.slice().sort(function(a,b){ return sums[b]-sums[a]; });
  var max = sums[order[0]];
  $("cat-panel").innerHTML = "<h3>Combined implied value by category <span class='r'>207 rows</span></h3><div style='padding:8px 0 10px'>" +
    order.map(function(cn){
      var short = cn === "Onchain Capital Allocators" ? "Capital Allocators" : cn;
      return '<div class="bar-row"><span class="nm" title="' + cn + '">' + short + '</span><span class="tr"><span class="fl" style="display:block;width:' + (sums[cn]/max*100).toFixed(1) + '%"></span></span><span class="vl">' + fmtUSD(sums[cn]) + " · " + ns[cn] + "</span></div>";
    }).join("") + "</div>" +
    '<div class="note">Risk Curators dominate because the largest legitimate pre-token protocols are curator vaults (Steakhouse, Sentora, Gauntlet) plus allocators — bridges and exchanges are excluded from this board. Category medians are used only where a category has <b>n &ge; 10</b> priced peers (2 categories: Lending, Dexs); the other categories fall back to the overall priced median 0.2138, flagged per row in the dossier.</div>';
}
function calibSVG(w, h, mini){
  var padL = 48, padB = 26, padT = 12, padR = 16, iw = w - padL - padR, ih = h - padT - padB;
  var X = function(p){ return padL + p*iw; }, Y = function(p){ return padT + (1-p)*ih; };
  var s = '<svg width="100%" viewBox="0 0 ' + w + " " + h + '" style="display:block;overflow:visible" role="img" aria-label="Calibration plot: predicted versus observed launch rate by decile">';
  s += '<line x1="' + X(0) + '" y1="' + Y(0) + '" x2="' + X(0.65) + '" y2="' + Y(0.65) + '" stroke="#3A4E66" stroke-dasharray="4 3"/>';
  s += '<line x1="' + padL + '" y1="' + (padT+ih) + '" x2="' + (padL+iw) + '" y2="' + (padT+ih) + '" stroke="#27374A"/>';
  s += '<line x1="' + padL + '" y1="' + padT + '" x2="' + padL + '" y2="' + (padT+ih) + '" stroke="#27374A"/>';
  [0, 0.3, 0.6].forEach(function(t){
    s += '<text x="' + (padL-5) + '" y="' + (Y(t)+3) + '" fill="#5D7189" font-size="9" font-family="monospace" text-anchor="end">' + Math.round(t*100) + '%</text>';
    s += '<text x="' + X(t) + '" y="' + (h-5) + '" fill="#5D7189" font-size="9" font-family="monospace" text-anchor="middle">' + Math.round(t*100) + '%</text>';
  });
  CALIB.forEach(function(c){
    s += '<circle cx="' + X(c.pred) + '" cy="' + Y(c.obs) + '" r="' + (mini ? 3 : 4.5) + '" fill="#4CC2FF" stroke="#0A0E14" stroke-width="1"><title>Decile ' + c.d + ": predicted " + fmtPct(c.pred) + ", observed " + fmtPct(c.obs) + ", n=" + c.n + "</title></circle>";
  });
  s += '<text x="' + (padL+iw) + '" y="' + (padT+10) + '" fill="#5D7189" font-size="9" font-family="monospace" text-anchor="end">dashed = perfect</text>';
  return s + "</svg>";
}
function renderCalibPanel(){
  $("calib-panel").innerHTML = "<h3>Calibration — launch model <span class='r'>Phase 1 calibration · n=128</span></h3>" +
    '<div style="padding:8px 10px 2px">' + calibSVG(316, 168, true) + "</div>" +
    '<div class="kv"><span class="k">Calibration slope</span><span class="v">0.94 (1.00 = perfect)<span class="src">Phase 1 calibration set · n=128 · temporal hold-out</span></span></div>' +
    '<div class="kv"><span class="k">Brier score</span><span class="v">0.118 vs 0.197 climatology<span class="src">Phase 1 calibration set · n=128 · temporal hold-out</span></span></div>' +
    '<div class="kv"><span class="k">AUC</span><span class="v">0.79<span class="src">Phase 1 calibration set · n=128 · temporal hold-out</span></span></div>' +
    '<div class="note">Predicted decile vs observed 12-month launch rate. Points on the dashed line are perfectly calibrated. Full plots and both hold-outs: <b>Backtest tab</b>.</div>';
}

