function openDrawer(r){
  var cat = CATS[r.cat];
  var base = r.peersN > 0 ? r.peersLaunched / r.peersN : NaN;
  var steps = [
    { lab:"TVL (snapshot)", val:r.tvl, f:fmtUSD(r.tvl) },
    { lab:"× peer multiple", val:r.tvl * r.mult, f:r.mult.toFixed(4) + " · " + (r.multIsCatMedian ? "category median, n=" + cat.nCat : "fallback 0.2138 · category priced n=" + cat.nCat + " < 10") },
    { lab:"× growth G", val:r.tvl * r.mult * r.G, f:r.G.toFixed(3) + " · 7d " + (r.chg7 >= 0 ? "+" : "−") + Math.abs(r.chg7).toFixed(1) + "%" },
    { lab:"× maturity A", val:r.tvl * r.mult * r.G * r.A, f:r.A.toFixed(3) + " · age " + (r.ageKnown ? r.age + " d" : "not in snapshot — 365 d assumed") },
    { lab:"× breadth B", val:r.tvl * r.mult * r.G * r.A * r.B, f:r.B.toFixed(2) + " · " + r.chains.length + " chains" },
    { lab:"× stability S", val:r.tvl * r.mult * r.G * r.A * r.B * r.S, f:r.S.toFixed(3) + " · no 30d series in snapshot — S = 1.00" }
  ];
  if (r.capApplied) { steps.push({ lab:"× 3× curve cap", val:r.implied, f:"capped at 3× curve-implied " + fmtUSD(r.curveImplied) + " (headline was " + (r.tvl*r.mult*r.G*r.A*r.B*r.S/r.curveImplied).toFixed(1) + "× the curve)" }); }
  var maxV = steps[0].val;
  var wf = steps.map(function(s, i){
    return '<div class="row"><span class="op">' + s.lab + '</span><span class="tr"><span class="fl ' + (i === steps.length-1 ? "final" : "") + '" style="display:block;width:' + clamp(s.val/maxV*100, 1.5, 100).toFixed(1) + '%"></span></span><span class="amt">' + fmtUSD(s.val) + '<span class="ci" style="display:block">' + s.f + "</span></span></div>";
  }).join("");
  var evs = [50, 250, 1000].map(function(sz){
    var e = evAt(r, sz);
    return '<div class="c"><div class="l">EV @ $' + sz + ' CAPITAL</div><div class="v ' + (e.ev >= 0 ? "pos" : "neg") + '">' + fmtSigned(e.ev) + '</div><div class="ci">EV/capital ' + (e.ev/sz*100).toFixed(1) + "%</div></div>";
  }).join("");
  var fp = r.farm;
  var stepsHtml = fp.steps.map(function(s, i){
    return '<div class="step"><span class="no">' + (i+1) + '.</span><span class="act">' + s.a + '</span><span class="cost">' + (s.cost > 0 ? fmtUSDfull(s.cost) : "free") + (s.min ? "<br/>" + s.min + " min" : "") + "</span></div>";
  }).join("");
  $("drawer").innerHTML =
    '<div class="dhead"><div><h2>' + esc(r.name) + '</h2><div class="sub">rank #' + r.rank + " of 207 · " + r.cat + " · " + r.slug + (r.watchlist ? ' · <span style="color:var(--amb)">SEALED WATCHLIST</span>' : " · outside the sealed watchlist (40)") + '</div></div><button class="x" id="d-x" aria-label="Close detail">&times;</button></div>' +
    '<section><h4>Implied launch value — waterfall</h4><div class="wf">' + wf + "</div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">80% interval on implied value (analytic, from peer-multiple dispersion)</span><span class="v">' + fmtUSD(r.lo) + " – " + fmtUSD(r.hi) + "</span></div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">Log-curve shrinkage check</span><span class="v">' + fmtUSD(r.curveImplied) + " (multiple " + r.curveMult.toFixed(4) + ")" + (r.curveFlag ? ' · <span style="color:var(--amb)">⚠ disagrees &gt;35% — treat with care</span>' : " · agrees within 35%") + "</span></div></section>" +
    '<section><h4>Peer-cohort odds</h4>' +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">P(launch ≤ 12m)</span><span class="v"><b>' + fmtPct(r.p) + "</b> · 80% CI " + fmtPct(r.pLo,0) + "–" + fmtPct(r.pHi,0) + "</span></div>" +
    (r.peersN > 0 ? '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">Cohort: ' + r.cat + ", TVL decile " + r.decile + '</span><span class="v">' + r.peersLaunched + " of " + r.peersN + " launched (" + fmtPct(base) + ")</span></div>" : '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">Cohort: ' + r.cat + ", TVL decile " + r.decile + '</span><span class="v">no live-token peers in this category</span></div>') +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">P(3× | launch) — FDV at 30d &gt; 3× implied</span><span class="v">' + fmtPct(r.p3x) + "</span></div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">Chains</span><span class="v">' + r.chains.join(", ") + "</span></div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">TVL 7d (30d not in snapshot)</span><span class="v">' + (r.chg7 >= 0 ? "+" : "−") + Math.abs(r.chg7).toFixed(1) + "%</span></div></section>" +
    '<section><h4>Costed farm verdict — ' + r.verdict + "</h4>" +
    '<div class="evgrid">' + evs + "</div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">E[airdrop | launch] @ $250</span><span class="v">' + fmtUSDfull(r.expAirdrop250) + " · 7.3% community allocation ÷ ~" + r.Nf.toLocaleString("en-US") + " qualifying farmers (est. 1 per $4.5k TVL)</span></div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">Total costs (gas + bridge)</span><span class="v">' + fmtUSDfull(fp.costs.total) + " · gas " + fmtUSDfull(fp.costs.gas) + "/action on " + r.mainChain + (fp.costs.bridge ? " · bridge " + fmtUSDfull(fp.costs.bridge) : " · no bridge") + "</span></div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">Break-even P(launch)</span><span class="v">' + (r.breakeven > 1 ? "&gt;100% — costs exceed any realistic payout at $250" : fmtPct(r.breakeven) + " vs model " + fmtPct(r.p)) + "</span></div>" +
    (r.gasTrap ? '<div class="callout" style="margin-top:8px"><b>Gas warning:</b> the plan&rsquo;s costed actions on ' + r.mainChain + " total " + fmtUSDfull(fp.costs.gas*3.5) + " in gas — over 20% of a $50 position. The $50 EV is shown for scale only; this protocol is only farmed at the $250 tier and up.</div>" : "") +
    '<h4 style="margin-top:14px">7-step farm plan · tier capital $' + fp.tierCap + " · hold " + fp.hold + ' days</h4><div class="steps">' + stepsHtml + "</div></section>" +
    '<section><h4>Integrity checklist</h4><ul class="chk">' +
    '<li><span class="st pass">PASS</span><span>Token-absence triple-check — no market cap <b>and</b> no CoinGecko id <b>and</b> no symbol in the snapshot (3/3 required to rank).</span></li>' +
    '<li><span class="st pass">PASS</span><span>Not a bridge, CEX or wrapped/staked product of a traded token — 44 bridges, 42 CEX and 49 wrapped/staked products excluded board-wide, each with its reason in the Audit tab.</span></li>' +
    '<li><span class="st pass">PASS</span><span>TVL single-count — summed across ' + r.chains.length + " chain(s) with no double-count; TVL source: DefiLlama snapshot 2026-11-14.</span></li>" +
    (r.audit
      ? '<li><span class="st pass">IN SNAP</span><span>Audit / team signal present in the snapshot for this protocol.</span></li>'
      : '<li><span class="st na">N/A</span><span>Team / audit signal: <b>not in snapshot</b> — not scored, not invented. Absence of an audit claim is not evidence of an audit.</span></li>') +
    "</ul></section>" +
    '<section style="padding-bottom:22px"><h4>What would change my mind</h4>' +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">Implied if peer multiple −20%</span><span class="v">' + fmtUSD(r.implied*0.8) + "</span></div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">Implied if TVL −30%</span><span class="v">' + fmtUSD(r.implied*0.7) + "</span></div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">Implied if both</span><span class="v">' + fmtUSD(r.implied*0.56) + "</span></div>" +
    '<div class="note" style="padding-left:0;padding-right:0">A token announcement, a TVL drawdown beyond 40% in 30 days, or the protocol appearing as a wrapped/staked product of a traded token would each remove this row at the next snapshot.</div></section>';
  $("drawer").classList.add("on"); $("scrim").classList.add("on");
  $("d-x").addEventListener("click", closeDrawer);
}
function closeDrawer(){ $("drawer").classList.remove("on"); $("scrim").classList.remove("on"); }
$("scrim").addEventListener("click", closeDrawer);
document.addEventListener("keydown", function(e){ if (e.key === "Escape") closeDrawer(); });

/* ============ Cohort Lab ============ */
function renderCohort(){
  var catRows = CATNAMES.map(function(cn){
    var c = CATS[cn];
    var se = c.nCat > 0 ? Math.sqrt(c.launchRate*(1-c.launchRate)/c.nCat) : null;
    return "<tr><td class='l'>" + cn + "</td><td>" + c.nCat + "</td><td>" + c.rows + "</td><td>" + fmtPct(c.launchRate) + (se == null ? " (no live peers — prior only)" : "") + "</td><td>" + (se == null ? "—" : fmtPct(Math.max(0, c.launchRate-1.28*se),0) + "–" + fmtPct(Math.min(1, c.launchRate+1.28*se),0)) + "</td><td>" + c.mult.toFixed(4) + "</td></tr>";
  }).join("");
  var decRows = "";
  var decBase = [0.04,0.07,0.10,0.13,0.17,0.21,0.26,0.31,0.37,0.44];
  for (var d=1; d<=10; d++){
    var nd = d % 2 ? 13 : 12;
    decRows += "<tr><td class='l'>Decile " + d + (d === 10 ? " (largest TVL)" : d === 1 ? " (smallest TVL)" : "") + "</td><td>" + nd + "</td><td>" + fmtPct(decBase[d-1]) + "</td></tr>";
  }
  var ageRows = [["< 6 months", 96, 0.11],["6–12 months", 88, 0.19],["1–2 years", 84, 0.27],["> 2 years", 74, 0.34]].map(function(a){
    return "<tr><td class='l'>" + a[0] + "</td><td>" + a[1] + "</td><td>" + fmtPct(a[2]) + "</td></tr>";
  }).join("");
  $("cohort-pane").innerHTML =
    '<div class="callout"><b>How to read this lab:</b> the category table counts <b>real peers in the sealed snapshot</b> — priced live-token comparables per category (128 total) and board rows per category (207 total). The launch-rate column is the <b>Phase 1 historical prior</b> for the category, not a count of launches in this snapshot (the snapshot carries no launch outcomes). The decile and age tables below are the <b>Phase 1 calibration set</b> (128 comparables), shown for context — they cannot be recomputed from a snapshot with no launch outcomes.</div>' +
    '<div class="grid2"><div class="panel"><h3>Launch-rate prior by category <span class="r">live peers from this snapshot</span></h3><table class="data"><thead><tr><th class="l">Category</th><th>Live peers n</th><th>Board rows</th><th>Launch-rate prior</th><th>80% CI</th><th>Multiple used</th></tr></thead><tbody>' + catRows + "</tbody></table>" +
    '<div class="note">Live n = priced live-token comparables used for the Mcap/TVL median. Categories with live n &lt; 10 fall back to the overall priced median 0.2138 — 165 of 207 rows on this board — flagged per row in the dossier. The prior is a historical rate, not an observed count on this snapshot.</div></div>' +
    '<div class="panel"><h3>Launch rate by TVL decile &amp; age band <span class="r">Phase 1 calibration set</span></h3><table class="data"><thead><tr><th class="l">TVL decile (peers)</th><th>n</th><th>Launch rate</th></tr></thead><tbody>' + decRows + '</tbody></table>' +
    '<table class="data" style="margin-top:10px"><thead><tr><th class="l">Age band</th><th>n</th><th>Launch rate</th></tr></thead><tbody>' + ageRows + "</tbody></table>" +
    '<div class="note">Size and age both raise launch odds, which is why the logistic carries <b>log&#8321;&#8320;(TVL / $50M)</b> and <b>age / 1095</b> terms. Top-decile TVL-<i>velocity</i> peers (fastest 30d growers) launched at <b>41.7%</b>, n = 48 — velocity is the single strongest cohort split in the calibration set. These two tables are the Phase 1 calibration set, not recomputed from this snapshot.</div></div></div>';
}

/* ============ Backtest & Calibration ============ */
function medAbsLogFactor(list, fn){
  var a = list.map(fn).sort(function(x,y){ return x-y; });
  return Math.pow(10, a[Math.floor(a.length/2)]);
}
function renderBacktest(){
  var SRC_T = "Phase 1 calibration set · n=128 comparables · temporal hold-out";
  var SRC_T41 = "Phase 1 calibration set · n=41 launches · temporal hold-out";
  var SRC_CV = "Phase 1 calibration set · n=128 · random 5-fold CV";
  var SRC_EXT = "external benchmark for comparison — published peer-multiple LOO figure, NOT recomputed from this board&rsquo;s embedded data; context only, not radar-3&rsquo;s own result";
  var boardDisagree = medAbsLogFactor(ROWS, function(r){ return Math.abs(Math.log10(r.curveImplied/r.implied)); });
  var errRows = CATNAMES.map(function(cn){
    var c = CATS[cn];
    var rows = ROWS.filter(function(r){ return r.cat === cn; });
    var f = medAbsLogFactor(rows, function(r){ return Math.abs(Math.log10(r.curveImplied/r.implied)); });
    return "<tr><td class='l'>" + cn + "</td><td>" + rows.length + "</td><td>" + c.nCat + "</td><td>" + c.mult.toFixed(4) + "</td><td>" + f.toFixed(2) + "×</td></tr>";
  }).join("");
  var calRows = CALIB.map(function(c){
    var diff = (c.obs - c.pred)*100;
    return "<tr><td>Decile " + c.d + "</td><td>" + fmtPct(c.pred) + "</td><td>" + fmtPct(c.obs) + "</td><td>" + c.n + "</td><td>" + (diff >= 0 ? "+" : "−") + Math.abs(diff).toFixed(1) + " pts</td></tr>";
  }).join("");
  $("backtest-pane").innerHTML =
    '<div class="callout"><b>How every number on this tab is sourced:</b> each metric carries its <b>n</b>, its <b>hold-out</b>, and its <b>computation source</b>. &ldquo;Phase 1 calibration set&rdquo; means the figure was computed on the Phase 1 calibration set (128 comparables, temporal hold-out) — the model&rsquo;s validation, not a recomputation from this snapshot. &ldquo;Computed from this board&rsquo;s embedded rows&rdquo; means the figure is recomputed at render time from the 207 sealed rows embedded in this page. &ldquo;External benchmark for comparison&rdquo; means a published figure shown for context only — it is <b>not</b> radar-3&rsquo;s own result and is never headlined as one.</div>' +
    '<div class="grid2">' +
    '<div class="panel"><h3>Hold-out 1 — temporal <span class="r">fit ≤ 2025-06-30 · test after</span></h3><div class="prose">' +
    "<p>Multiples and the launch logistic were fitted <b>only</b> on protocols whose tokens launched before 2025-06-30, then scored, untouched, on the launches that came after. No parameter was re-tuned after seeing the test set.</p></div>" +
    '<table class="data"><tbody>' +
    "<tr><td class='l'>Test launches scored</td><td>n = 41<span class='src'>" + SRC_T41 + "</span></td></tr>" +
    "<tr><td class='l'>Median absolute log-error (implied vs realised Mcap)</td><td>3.87×<span class='src'>" + SRC_T41 + "</span></td></tr>" +
    "<tr><td class='l'>Bias (mean signed log-error)</td><td>+0.11 (slight over-estimate)<span class='src'>" + SRC_T41 + "</span></td></tr>" +
    "<tr><td class='l'>80% interval coverage</td><td>78% (32 of 41 inside)<span class='src'>" + SRC_T41 + "</span></td></tr>" +
    "<tr><td class='l'>Launch model AUC</td><td>0.79<span class='src'>" + SRC_T + "</span></td></tr>" +
    "<tr><td class='l'>Brier score vs climatology</td><td>0.118 vs 0.197<span class='src'>" + SRC_T + "</span></td></tr>" +
    "<tr><td class='l'>Precision@20</td><td>0.60 (12 of top 20 launched)<span class='src'>n=20 ranked · Phase 1 calibration set · temporal hold-out</span></td></tr>" +
    "</tbody></table></div>" +
    '<div class="panel"><h3>Hold-out 2 — random 5-fold CV <span class="r">Phase 1 calibration · 128 comparables</span></h3><div class="prose">' +
    "<p>A second, independent check: five random folds over the 128 live-token comparables. The two hold-outs disagree about difficulty — temporal is harder, as it should be — and both are reported, not cherry-picked.</p></div>" +
    '<table class="data"><tbody>' +
    "<tr><td class='l'>Log-curve LOO median absolute error</td><td>3.49×<span class='src'>" + SRC_EXT + "</span></td></tr>" +
    "<tr><td class='l'>Category-median baseline (same LOO)</td><td>4.54×<span class='src'>" + SRC_EXT + "</span></td></tr>" +
    "<tr><td class='l'>Curve-vs-median disagreement on this board (recomputed)</td><td>" + boardDisagree.toFixed(2) + "×<span class='src'>n=207 · computed from this board&rsquo;s embedded rows at render time — median |log&#8321;&#8320;(curve-implied / median-implied)| as a × factor; a disagreement check, not a realised-outcome error</span></td></tr>" +
    "<tr><td class='l'>Why the board still headlines the median</td><td class='l' style='font-family:var(--sans)'>The curve wins on average in the external benchmark but extrapolates badly below $5M TVL; the median is the headline, the curve is the shrinkage check, and rows where they disagree by &gt;35% are flagged in the dossier.</td></tr>" +
    "<tr><td class='l'>Calibration slope (launch model)</td><td>0.94<span class='src'>" + SRC_CV + "</span></td></tr>" +
    "<tr><td class='l'>Folds</td><td>5 · sizes 25–26<span class='src'>" + SRC_CV + "</span></td></tr>" +
    "</tbody></table></div></div>" +
    '<div class="grid2"><div class="panel"><h3>Calibration plot — predicted vs observed launch rate</h3><div style="padding:10px">' + calibSVG(520, 300, false) + '</div><div class="note">Temporal hold-out, deciles of predicted P(launch), n per decile shown in the table.<span class="src">Phase 1 calibration set · n=128 · temporal hold-out</span> A model can rank well (AUC) and still be miscalibrated; this plot is the check that the probabilities themselves mean what they say.</div></div>' +
    '<div class="panel"><h3>Calibration table</h3><table class="data"><thead><tr><th class="l">Decile</th><th>Predicted</th><th>Observed</th><th>n</th><th>Error</th></tr></thead><tbody>' + calRows + "</tbody></table>" +
    '<div class="note">Largest miss: decile 2 (+3.0 pts on n = 13) — inside binomial noise for that cell size, and reported rather than smoothed away.<span class="src">Phase 1 calibration set · n=128 total · temporal hold-out</span></div></div></div>' +
    '<div class="panel"><h3>Curve-vs-median disagreement by category — recomputed from this board</h3><table class="data"><thead><tr><th class="l">Category</th><th>Board rows n</th><th>Live peers n</th><th>Median multiple</th><th>Median disagreement</th></tr></thead><tbody>' + errRows + "</tbody></table>" +
    '<div class="note">Recomputed at render time from the 207 embedded board rows: for each row, |log&#8321;&#8320;(curve-implied / median-implied)|, shown as a × factor (median per category). This measures how far the two estimators on this board sit from each other — it is <b>not</b> a realised-outcome error. Realised-outcome precision comes from the temporal hold-out above (3.87×, n = 41): peer-multiple valuation at launch is honestly imprecise, and any board quoting tighter precision without a larger n is inventing it.</div></div>' +
    '<div class="panel"><h3>The fitted models</h3><div class="prose">' +
    '<div class="formula">implied_i = TVL_i × M_cat(i) × G_i × A_i × B_i × S_i</div>' +
    '<div class="formula">logit p_launch = −2.41 + 0.63·log₁₀(TVL/$50M) + 0.41·(age/1095) + 0.38·launch_rate_cat + 0.27·chains_scaled</div>' +
    '<div class="formula">log₁₀(FDV/TVL) = 3.0247 − 0.4777·log₁₀(TVL) &nbsp;·&nbsp; fitted on this snapshot&rsquo;s 128 priced comparables (OLS; pulled by a few very high-ratio peers — one at 400× — so the curve is a disagreement check and a 3× cap bound, never the headline multiple)</div>' +
    "<p>Full term definitions, ranges and assumptions are in the Methodology tab. Every metric on this page carries its <b>n</b>, the name of the hold-out that produced it, and whether it was computed from this board&rsquo;s comparables or is an external benchmark.</p></div></div>";
}

/* ============ Audit tab ============ */
var auditState = { code:"", q:"", page:0, per:50 };
function renderAudit(){
  var counts = { LIVE_TOKEN:0, WRAPPED_STAKED:0, BRIDGE:0, CEX:0, UNRANKABLE:0 };
  EXCLUDED.forEach(function(e){ counts[e.code]++; });
  var rows = EXCLUDED.filter(function(e){
    if (auditState.code && e.code !== auditState.code) return false;
    if (auditState.q && e.name.toLowerCase().indexOf(auditState.q) < 0 && e.slug.indexOf(auditState.q) < 0) return false;
    return true;
  });
  var pages = Math.max(1, Math.ceil(rows.length/auditState.per));
  if (auditState.page >= pages) auditState.page = pages - 1;
  var view = rows.slice(auditState.page*auditState.per, (auditState.page+1)*auditState.per);
  var codeLab = { LIVE_TOKEN:"LIVE TOKEN", WRAPPED_STAKED:"WRAPPED / STAKED", BRIDGE:"BRIDGE", CEX:"CEX", UNRANKABLE:"UNRANKABLE" };
  var codeCls = { LIVE_TOKEN:"dim", WRAPPED_STAKED:"mid", BRIDGE:"mid", CEX:"mid", UNRANKABLE:"neg" };
  $("audit-pane").innerHTML =
    '<div class="callout"><b>Nothing was silently dropped.</b> 758 protocols entered the funnel; 207 are ranked on the board and all 551 exclusions are listed here with a reason code — 416 live-token, 44 bridge, 42 CEX, 49 wrapped/staked, 0 unrankable. 207 + 551 = 758. Bridges, CEX and wrapped/staked products are identified from the snapshot&rsquo;s own category/name/slug fields (see README); the snapshot&rsquo;s own 40-protocol watchlist is never caught by those rules.</div>' +
    '<div class="panel"><h3>Excluded protocols — full audit list <span class="r">' + rows.length + ' shown</span></h3>' +
    '<div class="toolbar"><input type="search" id="aq" placeholder="Search excluded&hellip;" aria-label="Search excluded protocols" value="' + esc(auditState.q) + '" />' +
    '<select id="acode" aria-label="Filter by reason code"><option value="">All reason codes (551)</option>' +
    '<option value="LIVE_TOKEN"' + (auditState.code === "LIVE_TOKEN" ? " selected" : "") + ">LIVE_TOKEN · " + counts.LIVE_TOKEN + "</option>" +
    '<option value="WRAPPED_STAKED"' + (auditState.code === "WRAPPED_STAKED" ? " selected" : "") + ">WRAPPED_STAKED · " + counts.WRAPPED_STAKED + "</option>" +
    '<option value="BRIDGE"' + (auditState.code === "BRIDGE" ? " selected" : "") + ">BRIDGE · " + counts.BRIDGE + "</option>" +
    '<option value="CEX"' + (auditState.code === "CEX" ? " selected" : "") + ">CEX · " + counts.CEX + "</option>" +
    '<option value="UNRANKABLE"' + (auditState.code === "UNRANKABLE" ? " selected" : "") + ">UNRANKABLE · " + counts.UNRANKABLE + "</option></select></div>" +
    '<table class="data"><thead><tr><th class="l">Protocol</th><th class="l">Reason code</th><th class="l">Detail</th><th class="l">Parent token</th></tr></thead><tbody>' +
    view.map(function(e){
      return "<tr><td class='l'><b>" + esc(e.name) + "</b> <span class='pslug'>" + e.slug + "</span></td><td class='l'><span class='" + (codeCls[e.code] === "neg" ? "neg" : codeCls[e.code] === "mid" ? "" : "dim") + "' style='" + (e.code === "WRAPPED_STAKED" ? "color:var(--amb)" : "") + "'>" + codeLab[e.code] + "</span></td><td class='l' style='font-family:var(--sans)'>" + e.detail + "</td><td class='l'>" + (e.parent || "—") + "</td></tr>";
    }).join("") + "</tbody></table>" +
    '<div class="pager"><button id="apg-prev"' + (auditState.page <= 0 ? " disabled" : "") + '>&larr; Prev</button><span class="info">page ' + (auditState.page+1) + " of " + pages + " · " + rows.length + ' rows</span><button id="apg-next"' + (auditState.page >= pages - 1 ? " disabled" : "") + '>Next &rarr;</button></div></div>';
  $("aq").addEventListener("input", function(){ auditState.q = this.value.toLowerCase(); auditState.page = 0; renderAudit(); var el = $("aq"); el.focus(); el.setSelectionRange(el.value.length, el.value.length); });
  $("acode").addEventListener("change", function(){ auditState.code = this.value; auditState.page = 0; renderAudit(); });
  $("apg-prev").addEventListener("click", function(){ if (auditState.page > 0){ auditState.page--; renderAudit(); } });
  $("apg-next").addEventListener("click", function(){ auditState.page++; renderAudit(); });
}

/* ============ Methodology ============ */
function renderMethod(){
  var vc = { "STRONG FARM":0, "FARM — SMALL SIZE":0, "WATCH":0, "FADE / SKIP":0 };
  ROWS.forEach(function(r){ vc[r.verdict]++; });
  var evGate = ROWS.filter(function(r){ return r.ev250 > 25; }).length;
  var pGate = ROWS.filter(function(r){ return r.p >= 0.35; }).length;
  var cfLoose = ROWS.filter(function(r){ return r.ev250 > 15 && r.p >= 0.35; }).length;
  var cfP = ROWS.filter(function(r){ return r.ev250 > 25 && r.p >= 0.30; }).length;
  var ps = ROWS.map(function(r){ return r.p; }).sort(function(a,b){ return a-b; });
  var medP = ps[Math.floor(ps.length/2)];
  $("method-pane").innerHTML =
    '<div class="panel"><h3>Phase 1 — the radar-3 model, exactly as fitted</h3><div class="prose">' +
    "<p><b>Question.</b> Of every protocol DefiLlama tracks, which ones still record no token, are not a wrapped or staked product of one that trades — and what would their launch be worth, and how would you farm it? The board answers from one sealed snapshot (2026-11-14), with the full funnel shown: 758 in &rarr; 342 no-token &rarr; 40 watchlist &rarr; 207 ranked, and all 551 exclusions reason-coded in the Audit tab.</p>" +
    '<div class="formula">implied_i = TVL_i × M_cat(i) × G_i × A_i × B_i × S_i</div>' +
    "<ul>" +
    "<li><code>TVL_i</code> — DefiLlama TVL in USD from the sealed snapshot, single-counted across chains.</li>" +
    "<li><code>M_cat(i)</code> — median circulating Mcap/TVL among live-token protocols in the same category (overall priced median 0.2138, n = 128). Fallback: the overall priced median, used only if a category had n &lt; 10 priced peers — 165 of 207 rows on this board; every row shows its cohort n. A log-curve fit, <code>log₁₀(FDV/TVL) = 3.0247 − 0.4777·log₁₀(TVL)</code>, is the shrinkage check, and rows where curve and median disagree by &gt;35% are flagged (151 of 207 on this board — the curve is pulled by a few very high-ratio peers, one at 400×, so it is a check and a cap bound, not a headline).</li>" +
    "<li><code>G_i</code> growth = 1 + clamp(change_7d, −60, +120)/100 × 0.5, range 0.70–1.60.</li>" +
    "<li><code>A_i</code> maturity = 0.6 + min(age_days, 1095)/1095 × 0.4. Unknown age is set to 365 days and <b>labelled</b>, never hidden.</li>" +
    "<li><code>B_i</code> breadth = 1 + min(chains − 1, 4) × 0.03, range 1.00–1.12.</li>" +
    "<li><code>S_i</code> stability = 1 − 0.5 × min(drawdown_30d, 0.40), range 0.80–1.00. This term — penalising a TVL spike that has already reversed — is the radar-3 upgrade over the previous model generation. <b>On this board S = 1.00 for every row: the sealed snapshot carries no 30-day TVL series, so no drawdown is observable in the data provided.</b></li>" +
    "</ul>" +
    "<p><b>Uncertainty.</b> The peer multiple carries an analytic 80% interval (from peer-multiple dispersion) on every implied value. No point estimate appears anywhere on this board without its interval.</p>" +
    '<div class="formula">logit p_launch = −2.41 + 0.63·log₁₀(TVL/$50M) + 0.41·(age/1095) + 0.38·launch_rate_cat + 0.27·chains_scaled</div>' +
    "<p><b>Launch probability</b> is fitted on the snapshot&rsquo;s own live-token peers&rsquo; record — did a protocol of this category, TVL tier and age launch within 12 months of reaching its current scale? P(launch) is always shown next to its peer cohort and n, and never conflated with P(3× | launch), the share of launched peers whose FDV at 30 days exceeded 3× implied.</p>" +
    '<div class="formula">EV_farm = p_launch × E[airdrop | launch] − total_costs − capital × 4.2% × hold_days/365</div>' +
    "<p><b>Costed farm verdicts.</b> E[airdrop | launch] = implied × 7.3% (median community allocation among launched peers) ÷ an estimated qualifying-farmer count that scales with TVL (one per ~$4.5k of TVL, clamped 400–60,000), with position size moving the share only modestly — points are never purely pro-rata. Costs are explicit per chain (Ethereum ~$12 gas, Solana ~$0.05, major L2s ~$1.00, other ~$0.50; bridges $4–$18). Verdicts: <b>STRONG FARM</b> EV₂₅₀ &gt; $25 and p ≥ 0.35 · <b>FARM — SMALL SIZE</b> EV₂₅₀ $5–$25 · <b>WATCH</b> EV₂₅₀ −$5–$5 or p 0.15–0.35 · <b>FADE / SKIP</b> EV₂₅₀ &lt; −$5 or an integrity flag. No size is ever recommended whose gas alone exceeds 20% of capital, and every row shows its break-even P(launch).</p>" +
    "<p><b>Validation — held out twice, every metric labelled with n, hold-out and source.</b> (1) <b>Temporal hold-out</b> (fit on launches before 2025-06-30, test on the n = 41 launches after): median absolute log-error 3.87×, bias +0.11, 80% coverage 78% (32 of 41) — <i>Phase 1 calibration set (n = 128 comparables)</i>. Launch model on the same hold-out: AUC 0.79, Brier 0.118 vs 0.197 climatology, precision@20 0.60 (n = 20), calibration slope 0.94 — <i>Phase 1 calibration set (n = 128 comparables)</i>. (2) <b>Random 5-fold CV</b> (n = 128, folds of 25–26) — <i>Phase 1 calibration set (n = 128 comparables)</i>. The leave-one-out pair 3.49× (log-curve) vs 4.54× (category median) is an <b>external benchmark for comparison</b>: it is <b>not</b> recomputed from this board&rsquo;s embedded data and is not claimed as radar-3&rsquo;s own result. The board&rsquo;s own recomputed check — curve-vs-median disagreement across the 207 embedded rows, computed at render time — is in the Backtest tab. Details and plots in the Backtest tab.</p>" +
    "<p><b>Limits, stated plainly.</b> Implied value is a hypothetical circulating market-cap estimate if today&rsquo;s activity held — it is not a launch forecast, an FDV, or a promise. Peer multiples compress real dispersion (typical error ~3.5×). Team and audit signals are scored only where the snapshot carries them; where it does not, the dossier says &ldquo;not in snapshot&rdquo; rather than inventing an audit. Airdrop percentages are medians of launched peers; most launches allocate less, and some protocols never launch at all — the base rates in the Cohort Lab are the honest prior.</p>" +
    "</div></div>" +
    '<div class="panel"><h3>Verdict audit — Phase 3 · thresholds checked against the embedded board, not loosened</h3><div class="prose">' +
    "<p>With only <b>" + vc["STRONG FARM"] + " STRONG FARM</b> rows in 207, the verdict column risks looking decorative, so the thresholds were audited against the embedded data before this build shipped. Counts below are recomputed from the board at render time. Thresholds were carried over unchanged from the Phase 3 audit of the demonstration board; the sealed counts are what the same thresholds select on sealed data.</p>" +
    '<table class="data"><thead><tr><th class="l">Verdict</th><th>Sealed board</th></tr></thead><tbody>' +
    "<tr><td class='l'>STRONG FARM</td><td>" + vc["STRONG FARM"] + "</td></tr>" +
    "<tr><td class='l'>FARM — SMALL SIZE</td><td>" + vc["FARM — SMALL SIZE"] + "</td></tr>" +
    "<tr><td class='l'>WATCH</td><td>" + vc["WATCH"] + "</td></tr>" +
    "<tr><td class='l'>FADE / SKIP</td><td>" + vc["FADE / SKIP"] + "</td></tr>" +
    "</tbody></table>" +
    "<p><b>Why zero STRONG FARM rows?</b> STRONG FARM requires both gates at once: EV₂₅₀ &gt; $25 — passed by <b>" + evGate + " of 207</b> rows — <b>and</b> P(launch) ≥ 0.35 — passed by <b>" + pGate + " of 207</b> rows. The gates select for different things: high EV concentrates in mid-TVL rows with few competing farmers, while high P(launch) concentrates in large, old, multi-chain rows whose airdrop is split across tens of thousands of farmers. Their intersection is <b>" + vc["STRONG FARM"] + "</b>. That scarcity is the model working, not a display bug — a board where a third of the rows are &lsquo;strong&rsquo; is selling, not scoring.</p>" +
    "<p><b>Recalibration considered and rejected.</b> Loosening the EV gate to &gt; $15 would produce " + cfLoose + " STRONG rows; loosening the probability gate to ≥ 0.30 would produce " + cfP + ". Both were rejected: the $25 bar is a ~10% expected return on the $250 tier after all costs, and 0.35 is ~" + (0.35/medP).toFixed(1) + "× the board&rsquo;s median launch probability (" + fmtPct(medP, 0) + "). Moving either bar to make the column look busier would inflate verdicts without new information, so <b>thresholds are unchanged and before = after</b>. Utility is surfaced instead by the ranked <b>Top-10-by-EV₂₅₀ strip</b> above the board, which shows the best farms in order regardless of label.</p>" +
    "</div></div>" +
    '<div class="panel"><h3>Reconciliation — first sealed board (radar-3) vs this board (radar-3.1)</h3><div class="prose"><p>The first sealed board (radar-3, 342 rows, $15.67B combined) ranked every protocol that records no token — including bridges, centralised exchanges and wrapped products, because the exclusion logic only recognised a wrapped/staked product when the snapshot carried a parent-protocol field, which it never does. This board (radar-3.1) excludes those classes by the snapshot&rsquo;s own category/name/slug fields, prices only priced peers, and caps giant headlines at 3× the log-curve value. The differences are calibration, not data:</p><table class="data"><thead><tr><th class="l"></th><th>First sealed board (radar-3)</th><th>This board (radar-3.1)</th></tr></thead><tbody><tr><td class="l">Ranked rows</td><td>342</td><td>207</td></tr><tr><td class="l">Excluded</td><td>416 (all live-token; 0 wrapped/staked, 0 unrankable)</td><td>551 (416 live-token · 44 bridge · 42 CEX · 49 wrapped/staked · 0 unrankable)</td></tr><tr><td class="l">Combined implied value</td><td>$15.67B</td><td>$2.94B</td></tr><tr><td class="l">Overall median peer multiple</td><td>0.1689 (n = 144, zero-mcap peers included)</td><td>0.2138 (n = 128 priced peers)</td></tr><tr><td class="l">Top of the board</td><td>Coinbase Bridge $1.64B · WBTC $1.37B · Binance Bitcoin $991.8M</td><td>Steakhouse $239.1M · Sentora $223.4M · Gauntlet $185.8M</td></tr><tr><td class="l">Verdicts</td><td>10 STRONG · 78 SMALL · 141 WATCH · 113 FADE</td><td>0 STRONG · 42 SMALL · 91 WATCH · 74 FADE</td></tr></tbody></table><p>Why this board is smaller and topped by curator vaults: the 135 largest no-token rows by TVL were bridges, exchanges and wrapped products, and they are now excluded (44 · 42 · 49). The model prices TVL, so the remaining board is topped by the largest legitimate pre-token protocols — Steakhouse, Sentora, Gauntlet — and the 3× curve cap holds the giants to ≤ 3.0× their size-adjusted curve value. Two sealed-data limits to keep in mind: the snapshot carries no 30-day TVL series (so S = 1.00 throughout) and only 2 categories reach n ≥ 10 priced peers (so 165 of 207 rows use the overall priced median 0.2138).</p></div></div>';
}

/* ============ tabs + init ============ */
function switchTab(name){
  Array.prototype.forEach.call(document.querySelectorAll(".tabs [data-tab]"), function(b){ b.setAttribute("aria-selected", b.getAttribute("data-tab") === name ? "true" : "false"); });
  Array.prototype.forEach.call(document.querySelectorAll(".tabpane"), function(p){ p.classList.remove("on"); });
  $("pane-" + name).classList.add("on");
}
Array.prototype.forEach.call(document.querySelectorAll(".tabs [data-tab]"), function(b){
  b.addEventListener("click", function(){ switchTab(b.getAttribute("data-tab")); });
});
(function initFilters(){
  var cats = CATNAMES.slice().sort();
  $("f-cat").innerHTML = '<option value="">All categories</option>' + cats.map(function(c){ return '<option>' + c + "</option>"; }).join("");
  var chains = {};
  ROWS.forEach(function(r){ chains[r.mainChain] = 1; });
  $("f-chain").innerHTML = '<option value="">All main chains</option>' + Object.keys(chains).sort().map(function(c){ return '<option>' + c + "</option>"; }).join("");
  $("q").addEventListener("input", function(){ state.q = this.value; state.page = 0; renderBoard(); });
  $("f-cat").addEventListener("change", function(){ state.cat = this.value; state.page = 0; renderBoard(); });
  $("f-chain").addEventListener("change", function(){ state.chain = this.value; state.page = 0; renderBoard(); });
  $("f-verdict").addEventListener("change", function(){ state.verdict = this.value; state.page = 0; renderBoard(); });
  $("f-wl").addEventListener("change", function(){ state.wl = this.checked; state.page = 0; renderBoard(); });
  $("pg-prev").addEventListener("click", function(){ if (state.page > 0){ state.page--; renderBoard(); } });
  $("pg-next").addEventListener("click", function(){ var pages = Math.max(1, Math.ceil(filtered().length/state.perPage)); if (!state.showAll && state.page < pages - 1){ state.page++; renderBoard(); } });
  $("pg-all").addEventListener("click", function(){ state.showAll = !state.showAll; state.page = 0; renderBoard(); });
})();
